// บันทึกการดูจาก player: { video_id, duration, completed, session_id }
const body = ($json.body && typeof $json.body === 'object') ? $json.body : ($json || {});
const id = String(body.video_id || body.videoId || body.id || '').trim();
const duration = Math.max(0, Math.min(3600, Number(body.duration || body.seconds || 0) || 0));
const sid = String(body.session_id || body.sid || 'anon').slice(0, 64);
return [{ json: { id, duration, sid, completed: body.completed === true, valid: id.length > 0,
  hint: id ? null : 'ต้องส่ง video_id' } }];

// อ้างค่าจาก node ที่ถือข้อมูลจริงทั้งสองฝั่ง
const ask = $('ตรวจข้อมูลการดู').first().json;
const res = $json || {};
if (!ask.valid) return [{ json: { success: false, error: 'video_id_required', hint: ask.hint } }];
return [{ json: { success: res.ok === true, video_id: ask.id, seconds: res.seconds || ask.duration,
  completionPct: res.completionPct || 0, completed: ask.completed, session_id: ask.sid } }];
